// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz a boolean that decides whether the callee should revert or succeed
    function testFuzz_property(bool calleeShouldRevert) public {
        // Deploy a helper that either reverts on call or records and succeeds.
        CalleeHelper helper = new CalleeHelper(calleeShouldRevert);

        // Attempt the forward call and observe whether it reverted by try/catch
        bool ok;
        bytes memory data = abi.encodeWithSignature("notify()");
        try c.forward(address(helper), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: If the callee does NOT revert on the low-level call, c.forward should not revert.
        // We deployed helper to succeed when calleeShouldRevert == false, so require ok == true in that case.
        assertTrue(calleeShouldRevert || ok);
    }
}

// Helper that either reverts on any call, or records that it was called and returns successfully.
contract CalleeHelper {
    bool public shouldRevert;
    bool public wasCalled;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    // match any call target; record and optionally revert
    fallback() external payable {
        if (shouldRevert) revert("helper forced revert");
        wasCalled = true;
    }
    receive() external payable {
        if (shouldRevert) revert("helper forced revert");
        wasCalled = true;
    }
    // convenience function so ABI-encoded notify() maps to a concrete function selector
    function notify() external payable {
        if (shouldRevert) revert("helper forced revert");
        wasCalled = true;
    }
}
